ops:
  defSumSave: [apiDefSumSave, ['統計']],

/* ---------------- 缺失彙整與統計一覽表：存到擁有者雲端硬碟「統計匯出」資料夾 ----------------
 * 前台算好整張表（含表頭、合併儲存格）傳過來，後台只負責寫入 Google 試算表。
 * 同名檔案已存在時覆寫內容（不另建新檔），回傳試算表連結。
 * args = { name:'缺失彙整一覽表_115_督導', rows:[[...]], merges:[[r1,c1,r2,c2]], head:表頭列數 }
 */
function statExportFolder_() {
  let folder = prop_('STAT_EXPORT_FOLDER_ID');
  if (folder) {   // 資料夾被刪除（或在垃圾桶）就重建
    try { if (JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files/' + folder + '?fields=trashed').getContentText()).trashed) folder = ''; } catch (e) { folder = ''; }
  }
  if (!folder) {
    const r = driveFetch_('https://www.googleapis.com/drive/v3/files?fields=id', { method: 'post', contentType: 'application/json',
      payload: JSON.stringify({ name: '統計匯出', mimeType: 'application/vnd.google-apps.folder' }) });
    folder = JSON.parse(r.getContentText()).id; setProp_('STAT_EXPORT_FOLDER_ID', folder);
  }
  return folder;
}
function apiDefSumSave(args, user) {
  const name = String(args.name || '').trim();
  if (!/^缺失彙整一覽表_[^\\\/'"]{1,60}$/.test(name)) throw new Error('檔名不正確');
  const rows = args.rows, merges = args.merges || [], head = Math.max(0, Math.min(5, +args.head || 0));
  if (!Array.isArray(rows) || !rows.length || rows.length > 3000) throw new Error('表格內容不正確');
  const nC = rows.reduce((a, r) => Math.max(a, Array.isArray(r) ? r.length : 0), 0);
  if (!nC || nC > 100) throw new Error('表格欄數不正確');
  // 數值保留數字，其餘一律文字；以「'」開頭避免被當成公式（CSV／試算表公式注入防護）
  const vals = rows.map(r => Array.from({ length: nC }, (_, i) => {
    const v = Array.isArray(r) ? r[i] : '';
    if (typeof v === 'number' && isFinite(v)) return v;
    const s = String(v == null ? '' : v).slice(0, 2000);
    return /^[=+\-@]/.test(s) ? "'" + s : s;
  }));
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const folder = statExportFolder_();
    const q = encodeURIComponent("'" + folder + "' in parents and trashed=false and mimeType='application/vnd.google-apps.spreadsheet' and name='" + name + "'");
    const hit = (JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files?q=' + q + '&fields=files(id)&pageSize=5').getContentText()).files || [])[0];
    const id = hit ? hit.id : JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files?fields=id', { method: 'post', contentType: 'application/json',
      payload: JSON.stringify({ name: name, mimeType: 'application/vnd.google-apps.spreadsheet', parents: [folder] }) }).getContentText()).id;
    const ss = SpreadsheetApp.openById(id);
    const sh = ss.getSheets()[0];
    ss.getSheets().slice(1).forEach(x => ss.deleteSheet(x));
    sh.setName('一覽表');
    // 清除舊內容、格式與合併
    sh.setFrozenRows(0); sh.setFrozenColumns(0);
    sh.getRange(1, 1, sh.getMaxRows(), sh.getMaxColumns()).breakApart();
    sh.clear();
    if (sh.getMaxRows() < vals.length) sh.insertRowsAfter(sh.getMaxRows(), vals.length - sh.getMaxRows());
    if (sh.getMaxColumns() < nC) sh.insertColumnsAfter(sh.getMaxColumns(), nC - sh.getMaxColumns());
    const all = sh.getRange(1, 1, vals.length, nC);
    sh.getRange(1, 1, vals.length, Math.min(4, nC)).setNumberFormat('@');   // 缺失代碼（如 5.10）須保留文字，不可變成數字
    all.setValues(vals);
    merges.forEach(m => { if (Array.isArray(m) && m.length === 4 && m[2] < vals.length && m[3] < nC) sh.getRange(m[0] + 1, m[1] + 1, m[2] - m[0] + 1, m[3] - m[1] + 1).merge(); });
    all.setBorder(true, true, true, true, true, true).setVerticalAlignment('middle').setFontSize(10);
    sh.getRange(1, 5, vals.length, Math.max(1, nC - 4)).setHorizontalAlignment('center');
    if (head) sh.getRange(1, 1, head, nC).setFontWeight('bold').setHorizontalAlignment('center').setWrap(true).setBackground('#e8eef7');
    sh.getRange(1, 4, vals.length, 1).setWrap(true);
    sh.setColumnWidth(1, 90); sh.setColumnWidth(2, 120); sh.setColumnWidth(3, 90); sh.setColumnWidth(4, 360);
    if (nC > 4) sh.setColumnWidths(5, nC - 4, 48);
    if (head) sh.setFrozenRows(head);
    SpreadsheetApp.flush();
    log_(user.Email, '缺失彙整匯出', '', { name: name, rows: vals.length, overwrite: !!hit });
    return { id: id, url: ss.getUrl(), name: name, overwrite: !!hit, savedAt: nowStr_() };
  } finally { lock.releaseLock(); }
}
